// Generated from vwap-precision-signals.pine — do not edit by hand.
window.PINE_SOURCE = "//@version=5\n// ============================================================================\n//  VWAP PRECISION SIGNALS (4-Rule Composite)\n//  Rules implemented:\n//   1. Time-Based VWAP  - session reset (Day/Week/Month) + sigma bands.\n//                         Snap-back signal when price re-enters the 2s band.\n//   2. Anchored VWAP    - auto-anchored at confirmed swing lows (or a manual\n//                         date). Close below it = trend may be losing steam.\n//   3. Previous VWAP Close - yesterday's final VWAP as a magnet/target level.\n//                         Touch + reclaim = bullish, touch + rejection = bearish.\n//   4. T-Size VWAP      - VWAP of \"big player\" bars only (volume > k x SMA50).\n//                         Divergence between big-money VWAP and crowd VWAP is\n//                         an early clue.\n//  Composite score = 0.25*R1 + 0.30*R2 + 0.20*R3 + 0.25*R4  (each -1..+1)\n//  BUY when score >= +0.35, SELL when score <= -0.35, otherwise wait.\n//\n//  NOTE: Rule 4 needs real volume data. On symbols without volume\n//  (e.g. NSE spot index ^NSEI) it shows n/a - use the index futures\n//  (NIFTY1!) or a stock chart instead.\n// ============================================================================\nindicator(\"VWAP Precision Signals (4-Rule)\", shorttitle=\"VWAP-PREC\", overlay=true, max_labels_count=500)\n\n// ------------------------------- Inputs -------------------------------------\ngrp1 = \"1 · Time-Based VWAP\"\nresetPeriod = input.string(\"Day\", \"Session reset\", options=[\"Day\", \"Week\", \"Month\"], group=grp1)\nbandMult1   = input.float(1.0, \"Inner band (sigma)\", step=0.25, minval=0.25, group=grp1)\nbandMult2   = input.float(2.0, \"Outer band (sigma)\", step=0.25, minval=0.5,  group=grp1)\nholdBars    = input.int(12, \"Signal hold (bars)\", minval=1, maxval=100, group=grp1)\n\ngrp2 = \"2 · Anchored VWAP\"\nanchorMode = input.string(\"Auto (swing lows)\", \"Anchor mode\", options=[\"Auto (swing lows)\", \"Manual date\"], group=grp2)\nanchorTime = input.time(timestamp(\"01 Jan 2026 00:00 +0000\"), \"Manual anchor time (UTC)\", group=grp2)\npivotK     = input.int(5, \"Pivot strength (bars each side)\", minval=2, maxval=50, group=grp2)\n\ngrp3 = \"3 · Previous VWAP Close\"\nusePrev  = input.bool(true, \"Mark previous session VWAP close\", group=grp3)\ntouchPct = input.float(0.15, \"Touch zone (%)\", step=0.05, minval=0.0, group=grp3)\n\ngrp4 = \"4 · T-Size VWAP (big players)\"\nbigMult = input.float(3.0, \"Big-bar volume multiple of SMA50\", step=0.5, minval=1.5, group=grp4)\ndivThr  = input.float(0.15, \"Divergence trigger (%)\", step=0.05, minval=0.05, group=grp4)\n\ngrp5 = \"Display\"\nshowTable = input.bool(true, \"Show rule dashboard table\", group=grp5)\n\n// ------------------------- 1) Time-based session VWAP -----------------------\ntfSes      = resetPeriod == \"Day\" ? \"D\" : resetPeriod == \"Week\" ? \"W\" : \"M\"\nnewSession = timeframe.change(tfSes)\n\nfloat v  = nz(volume) > 0 ? volume : 1.0   // equal-weight fallback when the symbol has no volume\nfloat tp = hlc3\n\nvar float cumPV  = 0.0\nvar float cumV   = 0.0\nvar float cumP2V = 0.0\nif newSession or na(cumV[1])\n    cumPV  := 0.0\n    cumV   := 0.0\n    cumP2V := 0.0\ncumPV  += tp * v\ncumV   += v\ncumP2V += tp * tp * v\n\nfloat sesVwap = cumV > 0 ? cumPV / cumV : tp\nfloat sesSig  = math.sqrt(math.max(cumP2V / cumV - sesVwap * sesVwap, 0.0))\nfloat sigSafe = math.max(sesSig, syminfo.mintick)\nfloat zNow    = (close - sesVwap) / sigSafe\n\nfloat up1 = sesVwap + bandMult1 * sesSig\nfloat lo1 = sesVwap - bandMult1 * sesSig\nfloat up2 = sesVwap + bandMult2 * sesSig\nfloat lo2 = sesVwap - bandMult2 * sesSig\n\n// ------------------------- 2) Anchored VWAP ---------------------------------\nfloat plVal = ta.pivotlow(low, pivotK, pivotK)   // confirmed pivotK bars after the actual low\n\nbool anchorHit = switch anchorMode\n    \"Auto (swing lows)\" => not na(plVal)\n    \"Manual date\"       => time >= anchorTime and (na(time[1]) or time[1] < anchorTime)\n    => false\n\nvar float aCumPV = na\nvar float aCumV  = na\nvar float aVwap  = na\nif anchorHit or na(aCumPV)\n    aCumPV := tp * v\n    aCumV  := v\nelse\n    aCumPV += tp * v\n    aCumV  += v\naVwap := aCumPV / aCumV\n\n// ------------------------- 3) Previous session VWAP close -------------------\nvar float prevVwapClose = na\nvar float lastSesVwap   = na\nif newSession\n    prevVwapClose := lastSesVwap\nlastSesVwap := sesVwap\n\n// ------------------------- 4) T-Size VWAP (big players) ---------------------\nfloat vSma   = ta.sma(volume, 50)\nbool  hasVol = nz(volume) > 0\nbool  bigBar = hasVol and v > bigMult * vSma\n\nvar float tCumPV = 0.0\nvar float tCumV  = 0.0\nvar float tVwap  = na\nif newSession\n    tCumPV := 0.0\n    tCumV  := 0.0\nif bigBar\n    tCumPV += tp * v\n    tCumV  += v\ntVwap := tCumV > 0 ? tCumPV / tCumV : na\n\nfloat divg = not na(tVwap) ? (tVwap - sesVwap) / sesVwap : na   // big-money vs crowd\n\n// ------------------------- Rule evaluations ---------------------------------\n// R1 - snap-back mean reversion: price was outside the 2s band, then re-entered.\nbool r1BuyEvt  = zNow[1] <= -bandMult2 and zNow > -bandMult2\nbool r1SellEvt = zNow[1] >=  bandMult2 and zNow <  bandMult2\nbool r1Ext     = math.abs(zNow) >= bandMult2\n\nvar float r1Score = 0.0\nvar int   r1Age   = 9999\nif r1BuyEvt\n    r1Score := 1.0\n    r1Age   := 0\nelse if r1SellEvt\n    r1Score := -1.0\n    r1Age   := 0\nelse\n    r1Age += 1\n    if r1Age > holdBars\n        r1Score := 0.0\n\n// R2 - anchored VWAP regime filter.\nbool r2CrossDn = ta.crossunder(close, aVwap)   // warning: trend may be running out of steam\nbool r2CrossUp = ta.crossover(close, aVwap)    // trend reclaimed\nfloat r2Score = close > aVwap ? 1.0 : close < aVwap ? -1.0 : 0.0\n\n// R3 - previous session VWAP close as a magnet/target.\n// \"Visit then react\": the previous bar was inside the touch zone, the current bar crosses the wall.\nbool xUp = ta.crossover(close, prevVwapClose)\nbool xDn = ta.crossunder(close, prevVwapClose)\nbool nearWall = not na(prevVwapClose) and math.abs(close[1] - prevVwapClose) <= prevVwapClose * touchPct / 100\nbool r3BuyEvt  = usePrev and not newSession and nearWall and xUp\nbool r3SellEvt = usePrev and not newSession and nearWall and xDn\n\nvar float r3Score = 0.0\nvar int   r3Age   = 9999\nif r3BuyEvt\n    r3Score := 1.0\n    r3Age   := 0\nelse if r3SellEvt\n    r3Score := -1.0\n    r3Age   := 0\nelse\n    r3Age += 1\n    if r3Age > holdBars\n        r3Score := 0.0\n\n// R4 - big players drifting away from the crowd.\nbool dUp = not na(divg) and divg >=  divThr / 100\nbool dDn = not na(divg) and divg <= -divThr / 100\nbool r4BuyEvt  = dUp and not dUp[1]\nbool r4SellEvt = dDn and not dDn[1]\nfloat r4Score = dUp ? 1.0 : dDn ? -1.0 : 0.0\n\n// ------------------------- Composite verdict --------------------------------\nfloat score = 0.25 * r1Score + 0.30 * r2Score + 0.20 * r3Score + 0.25 * r4Score\nbool  buySig  = score >=  0.35 and score[1] <  0.35\nbool  sellSig = score <= -0.35 and score[1] > -0.35\n\n// ------------------------- Plots --------------------------------------------\ncolor C_VWAP  = #F0B90B\ncolor C_ANCH  = #1EAEDB\ncolor C_TSIZE = #FFD000\ncolor C_PREV  = #848E9C\ncolor C_GOOD  = #0ECB81\ncolor C_BAD   = #F6465D\n\npUp2 = plot(up2, \"VWAP +2s\", color=color.new(C_PREV, 55), style=plot.style_linebr)\npLo2 = plot(lo2, \"VWAP -2s\", color=color.new(C_PREV, 55), style=plot.style_linebr)\nfill(pUp2, pLo2, color=color.new(C_PREV, 94), title=\"VWAP band fill\")\nplot(up1, \"VWAP +1s\", color=color.new(C_PREV, 75), style=plot.style_linebr)\nplot(lo1, \"VWAP -1s\", color=color.new(C_PREV, 75), style=plot.style_linebr)\nplot(sesVwap, \"Session VWAP\", color=C_VWAP, linewidth=2)\nplot(aVwap, \"Anchored VWAP\", color=C_ANCH, linewidth=2)\nplot(tVwap, \"T-Size VWAP\", color=color.new(C_TSIZE, 0), linewidth=1, style=plot.style_steplinebr)\nplot(usePrev ? prevVwapClose : na, \"Prev session VWAP close\", color=color.new(C_PREV, 20), style=plot.style_steplinebr)\n\nplotshape(buySig,  \"Composite BUY\",  style=shape.triangleup,   location=location.belowbar, color=C_GOOD, size=size.tiny, text=\"BUY\",  textcolor=C_GOOD)\nplotshape(sellSig, \"Composite SELL\", style=shape.triangledown, location=location.abovebar, color=C_BAD,  size=size.tiny, text=\"SELL\", textcolor=C_BAD)\nbgcolor(score >= 0.35 ? color.new(C_GOOD, 92) : score <= -0.35 ? color.new(C_BAD, 92) : na, title=\"Verdict background\")\n\n// Event labels (confirmed bars only, to cut intrabar repaint noise)\nif barstate.isconfirmed\n    if r1BuyEvt\n        label.new(bar_index, na, \"R1 snap-back\", yloc=yloc.belowbar, style=label.style_label_up, color=color.new(C_GOOD, 25), textcolor=color.white, size=size.tiny)\n    if r1SellEvt\n        label.new(bar_index, na, \"R1 fade\", yloc=yloc.abovebar, style=label.style_label_down, color=color.new(C_BAD, 25), textcolor=color.white, size=size.tiny)\n    if r2CrossDn\n        label.new(bar_index, na, \"R2 lost aVWAP\", yloc=yloc.abovebar, style=label.style_label_down, color=color.new(C_BAD, 55), textcolor=color.white, size=size.tiny)\n    if r2CrossUp\n        label.new(bar_index, na, \"R2 back above aVWAP\", yloc=yloc.belowbar, style=label.style_label_up, color=color.new(C_GOOD, 55), textcolor=color.white, size=size.tiny)\n    if r3BuyEvt\n        label.new(bar_index, na, \"R3 wall reclaimed\", yloc=yloc.belowbar, style=label.style_label_up, color=color.new(C_GOOD, 40), textcolor=color.white, size=size.tiny)\n    if r3SellEvt\n        label.new(bar_index, na, \"R3 wall rejected\", yloc=yloc.abovebar, style=label.style_label_down, color=color.new(C_BAD, 40), textcolor=color.white, size=size.tiny)\n    if r4BuyEvt\n        label.new(bar_index, na, \"R4 smart money up\", yloc=yloc.belowbar, style=label.style_label_up, color=color.new(C_TSIZE, 35), textcolor=color.black, size=size.tiny)\n    if r4SellEvt\n        label.new(bar_index, na, \"R4 smart money out\", yloc=yloc.abovebar, style=label.style_label_down, color=color.new(C_BAD, 55), textcolor=color.white, size=size.tiny)\n\n// ------------------------- Dashboard table ----------------------------------\nvar table dash = table.new(position.top_right, 2, 6, bgcolor=color.new(color.black, 20), border_width=1, border_color=color.new(color.gray, 60))\n\nf_state(float s, bool ext) =>\n    ext ? \"EXTENDED\" : s > 0 ? \"BULLISH\" : s < 0 ? \"BEARISH\" : \"NEUTRAL\"\n\nf_col(float s) => s > 0 ? C_GOOD : s < 0 ? C_BAD : C_PREV\n\nif showTable and barstate.islast\n    table.cell(dash, 0, 0, \"RULE\", text_color=color.white, text_size=size.tiny, bgcolor=color.new(color.gray, 70))\n    table.cell(dash, 1, 0, \"STATE\", text_color=color.white, text_size=size.tiny, bgcolor=color.new(color.gray, 70))\n    table.cell(dash, 0, 1, \"1 Time VWAP\", text_color=color.silver, text_size=size.tiny)\n    table.cell(dash, 1, 1, f_state(r1Score, r1Ext and r1Score == 0), text_color=f_col(r1Score), text_size=size.tiny)\n    table.cell(dash, 0, 2, \"2 Anchored\", text_color=color.silver, text_size=size.tiny)\n    table.cell(dash, 1, 2, f_state(r2Score, false), text_color=f_col(r2Score), text_size=size.tiny)\n    table.cell(dash, 0, 3, \"3 Prev close\", text_color=color.silver, text_size=size.tiny)\n    table.cell(dash, 1, 3, f_state(r3Score, false), text_color=f_col(r3Score), text_size=size.tiny)\n    table.cell(dash, 0, 4, \"4 T-Size\", text_color=color.silver, text_size=size.tiny)\n    table.cell(dash, 1, 4, na(tVwap) ? \"N/A (no volume)\" : f_state(r4Score, false), text_color=na(tVwap) ? color.gray : f_col(r4Score), text_size=size.tiny)\n    table.cell(dash, 0, 5, \"VERDICT\", text_color=color.white, text_size=size.small, bgcolor=color.new(color.gray, 70))\n    table.cell(dash, 1, 5, (score >= 0.35 ? \"BUY \" : score <= -0.35 ? \"SELL \" : \"WAIT \") + str.tostring(math.round(math.abs(score) * 100)) + \"%\", text_color=score >= 0.35 ? C_GOOD : score <= -0.35 ? C_BAD : color.silver, text_size=size.small)\n\n// ------------------------- Alerts -------------------------------------------\nalertcondition(buySig,   \"VWAP-PREC Composite BUY\",  \"VWAP Precision: composite BUY (score >= +0.35)\")\nalertcondition(sellSig,  \"VWAP-PREC Composite SELL\", \"VWAP Precision: composite SELL (score <= -0.35)\")\nalertcondition(r1BuyEvt, \"R1 Snap-back BUY\",         \"VWAP Precision R1: price snapped back inside the lower band - reversion BUY setup\")\nalertcondition(r1SellEvt,\"R1 Fade SELL\",             \"VWAP Precision R1: price snapped back inside the upper band - reversion SELL setup\")\nalertcondition(r2CrossDn,\"R2 Lost Anchored VWAP\",    \"VWAP Precision R2: price closed below the anchored VWAP - trend may be losing steam\")\nalertcondition(r2CrossUp,\"R2 Reclaimed Anchored VWAP\",\"VWAP Precision R2: price back above the anchored VWAP\")\nalertcondition(r3BuyEvt, \"R3 Wall Reclaimed\",        \"VWAP Precision R3: previous VWAP close touched and reclaimed from below\")\nalertcondition(r3SellEvt,\"R3 Wall Rejected\",         \"VWAP Precision R3: previous VWAP close touched and rejected from above\")\nalertcondition(r4BuyEvt, \"R4 Smart Money Accumulating\",\"VWAP Precision R4: big-player VWAP above crowd VWAP by threshold\")\nalertcondition(r4SellEvt,\"R4 Smart Money Distributing\",\"VWAP Precision R4: big-player VWAP below crowd VWAP by threshold\")\n";
